241	        }
242	        String digits = telephone.substring(1);
243	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
244	        if (digits.length() <= countryCodeLength) {
245	            return telephone;
246	        }
247	        String countryCode = digits.substring(0, countryCodeLength);
248	        String national = digits.substring(countryCodeLength);
249	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
250	        for (int i = 0; i < national.length(); i++) {
251	            if (i % 3 == 0) {
252	                grouped.append(' ');
253	            }
254	            grouped.append(national.charAt(i));
255	        }
256	        return grouped.toString();
257	    }
